using UnityEngine;
using UnityEngine.UIElements;

/// <summary>
/// Screen-space interaction tag that follows the mouse cursor while an
/// interactable is hovered. Driven by <see cref="WorldInteractTagPresenter"/>
/// when a hover is active the presenter calls <see cref="Show"/> with the
/// prompt text; the tag then follows the cursor each frame until
/// <see cref="HideTag"/> is called.
///
/// Lives as a pre-existing UIDocument under the UI manager so designers can
/// customise the UXML/USS. Uses the Flynn mono palette (black bg, 1px white outline).
/// </summary>
public class InteractTagPanel : UIToolkitPanel
{
    private Label _label;
    private VisualElement _root;

    protected override bool Bind(VisualElement root)
    {
        _root = root.Q<VisualElement>("InteractTagRoot");
        _label = root.Q<Label>("InteractTagLabel");
        return _root != null && _label != null;
    }

    private void LateUpdate()
    {
        if (!IsVisible || _root == null) return;

        var panel = _root.panel;
        if (panel == null) return;

        Vector2 mouse = Input.mousePosition;
        var contentRect = panel.visualTree.layout;
        float scaleX = contentRect.width > 0 ? Screen.width / contentRect.width : 1f;
        float scaleY = contentRect.height > 0 ? Screen.height / contentRect.height : 1f;

        _root.style.left = mouse.x / scaleX;
        _root.style.top = (Screen.height - mouse.y) / scaleY;
    }

    /// <summary>Show the tag with the given prompt text. It will follow the mouse cursor.</summary>
    public void Show(string text)
    {
        if (_label != null) _label.text = text;
        if (_root != null) _root.style.display = DisplayStyle.Flex;
        IsVisible = true;
        ApplyRootDisplay();
    }

    /// <summary>Hide the tag.</summary>
    public void HideTag()
    {
        if (_root != null) _root.style.display = DisplayStyle.None;
        IsVisible = false;
        ApplyRootDisplay();
    }

    private void ApplyRootDisplay()
    {
        if (Root != null)
            Root.style.display = IsVisible ? DisplayStyle.Flex : DisplayStyle.None;
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;
using Flynn.Events;

/// <summary>
/// Screen-space UI Toolkit panel that projects floating HP bars above ResourceNodes.
/// Driven by <see cref="UIManager"/> as <see cref="UIPanelId.ResourceHP"/>. Subscribes
/// to <see cref="ResourceDamaged"/> / <see cref="ResourceDepleted"/> on GameEventBus
/// and pools VisualElement bars. Bars are positioned by projecting world-space node
/// positions to panel coordinates via RuntimePanelUtils.
///
/// Bar style: white fill depleting left→right on a black background (Flynn mono).
/// Lives as a UIDocument under MANAGERS/UI.
/// </summary>
[RequireComponent(typeof(UIDocument))]
public class ResourceHPPanel : UIToolkitPanel
{
    [Header("Appearance")]
    [Tooltip("World-space height offset above the node origin.")]
    [SerializeField] private float _heightOffset = 1.6f;

    [Header("Timing")]
    [Tooltip("Seconds to keep the bar visible after the last hit.")]
    [SerializeField] private float _displayDuration = 3f;

    [Tooltip("Seconds for the fade-out animation.")]
    [SerializeField] private float _fadeDuration = 0.5f;

    [Tooltip("UXML template for a single health bar instance.")]
    [SerializeField] private VisualTreeAsset _healthBarTemplate;

    // ── Event bus subscription state ────────────────────────────────────────

    private bool _subscribed;

    // ── Pool & active tracking ─────────────────────────────────────────────

    private readonly Stack<VisualElement> _pool = new();
    private readonly Dictionary<ResourceNode, BarEntry> _active = new();

    private VisualElement _root;

    private struct BarEntry
    {
        public VisualElement Bar;
        public VisualElement Fill;
        public float HideTime;
        public bool Fading;
    }

    // ── Unity messages ──────────────────────────────────────────────────────

    protected override void OnEnable()
    {
        base.OnEnable();
        if (GameEventBus.Instance != null)
        {
            GameEventBus.Instance.Subscribe<ResourceDamaged>(OnResourceDamaged);
            GameEventBus.Instance.Subscribe<ResourceDepleted>(OnResourceDepleted);
        }
    }

    private void OnDisable()
    {
        if (GameEventBus.Instance != null && _subscribed)
        {
            GameEventBus.Instance.Unsubscribe<ResourceDamaged>(OnResourceDamaged);
            GameEventBus.Instance.Unsubscribe<ResourceDepleted>(OnResourceDepleted);
            _subscribed = false;
        }
    }

    private void TrySubscribe()
    {
        if (_subscribed || GameEventBus.Instance == null) return;
        GameEventBus.Instance.Subscribe<ResourceDamaged>(OnResourceDamaged);
        GameEventBus.Instance.Subscribe<ResourceDepleted>(OnResourceDepleted);
        _subscribed = true;
    }

    private void LateUpdate()
    {
        TrySubscribe();

        if (_root == null || Camera.main == null) return;

        float now = Time.time;
        List<ResourceNode> toRelease = null;

        foreach (var kvp in _active)
        {
            var node = kvp.Key;
            var entry = kvp.Value;

            // Node destroyed — release immediately
            if (node == null)
            {
                if (toRelease == null) toRelease = new List<ResourceNode>();
                toRelease.Add(node);
                continue;
            }

            // Project world position to panel coordinates
            Vector3 worldPos = node.transform.position + Vector3.up * _heightOffset;
            Vector2 panelPos = RuntimePanelUtils.CameraTransformWorldToPanel(
                _root.panel, worldPos, Camera.main);

            // Offset so bar centers above the node
            float barWidth = entry.Bar.resolvedStyle.width;
            entry.Bar.style.left = panelPos.x - barWidth * 0.5f;
            entry.Bar.style.top = panelPos.y;

            // Start fading when timer expires
            if (!entry.Fading && now >= entry.HideTime)
            {
                entry.Fading = true;
                entry.Bar.AddToClassList("health-bar--fading");
                entry.Bar.style.transitionDuration =
                    new List<TimeValue> { new TimeValue(_fadeDuration) };
            }

            // Check if fade finished
            if (entry.Fading && now >= entry.HideTime + _fadeDuration)
            {
                if (toRelease == null) toRelease = new List<ResourceNode>();
                toRelease.Add(node);
            }
        }

        if (toRelease != null)
        {
            foreach (var node in toRelease)
                ReleaseBar(node);
        }
    }

    // ── Binding ─────────────────────────────────────────────────────────────

    protected override bool Bind(VisualElement root)
    {
        _root = root.Q<VisualElement>("ResourceHPRoot");
        return _root != null;
    }

    // ── Event handlers ──────────────────────────────────────────────────────

    private void OnResourceDamaged(ResourceDamaged evt)
    {
        if (evt.Node == null || _root == null) return;

        if (!_active.TryGetValue(evt.Node, out var entry))
        {
            entry = AcquireBar(evt.Node);
            if (entry.Bar == null) return;
        }

        // Update fill width — white shrinks as HP depletes, revealing black bg
        float ratio = evt.Node.MaxHealth > 0
            ? (float)evt.RemainingHp / evt.Node.MaxHealth : 0f;
        entry.Fill.style.width = new StyleLength(Length.Percent(ratio * 100f));

        // Show and reset timer
        entry.Bar.AddToClassList("health-bar--visible");
        entry.Bar.RemoveFromClassList("health-bar--fading");
        entry.Bar.style.opacity = 1f;
        entry.Bar.style.transitionDuration = StyleKeyword.Null;
        entry.Fading = false;
        entry.HideTime = Time.time + _displayDuration;

        _active[evt.Node] = entry;
    }

    private void OnResourceDepleted(ResourceDepleted evt)
    {
        if (evt.Node == null) return;
        if (!_active.TryGetValue(evt.Node, out var entry)) return;

        entry.Fill.style.width = 0f;
        entry.Fading = true;
        entry.HideTime = Time.time;
        entry.Bar.AddToClassList("health-bar--fading");
        entry.Bar.style.transitionDuration =
            new List<TimeValue> { new TimeValue(_fadeDuration) };

        _active[evt.Node] = entry;
    }

    // ── Pool acquire / release ──────────────────────────────────────────────

    private BarEntry AcquireBar(ResourceNode node)
    {
        VisualElement bar;
        if (_pool.Count > 0)
        {
            bar = _pool.Pop();
        }
        else
        {
            bar = CreateBarElement();
        }

        bar.name = $"HPBar_{node.name}";
        _root.Add(bar);

        var fill = bar.Q<VisualElement>("BarFill");
        var entry = new BarEntry
        {
            Bar = bar,
            Fill = fill,
            HideTime = Time.time + _displayDuration,
            Fading = false,
        };

        _active[node] = entry;
        return entry;
    }

    private void ReleaseBar(ResourceNode node)
    {
        if (!_active.TryGetValue(node, out var entry)) return;

        entry.Bar.RemoveFromClassList("health-bar--visible");
        entry.Bar.RemoveFromClassList("health-bar--fading");
        entry.Bar.style.opacity = StyleKeyword.Null;
        entry.Bar.style.transitionDuration = StyleKeyword.Null;
        entry.Fill.style.width = new StyleLength(Length.Percent(100f));
        entry.Bar.name = "HealthBar_Pooled";

        _root.Remove(entry.Bar);
        _active.Remove(node);
        _pool.Push(entry.Bar);
    }

    // ── Bar element factory ─────────────────────────────────────────────────

    private VisualElement CreateBarElement()
    {
        if (_healthBarTemplate != null)
        {
            var container = _healthBarTemplate.CloneTree();
            return container.ElementAt(0) ?? container;
        }

        // Fallback: build in code (should not happen when template is assigned)
        var bar = new VisualElement { name = "HealthBar" };
        bar.AddToClassList("health-bar");

        var bg = new VisualElement { name = "BarBackground" };
        bg.AddToClassList("health-bar__bg");

        var fill = new VisualElement { name = "BarFill" };
        fill.AddToClassList("health-bar__fill");

        bg.Add(fill);
        bar.Add(bg);
        return bar;
    }
}

using System;
using UnityEngine;

/// <summary>
/// One inventory slot: an item kind plus how many of it are stacked here.
/// A slot holds a single item kind; the stack is capped by <see cref="ItemDefinition.maxStack"/>.
/// Kept as a small value type so the inventory model stays flat and expandable.
/// </summary>
[Serializable]
public struct InventorySlot
{
    public ItemDefinition item;
    public int count;

    public bool IsEmpty => item == null || count <= 0;

    /// <summary>Stack cap for whatever item this slot holds (1 when empty).</summary>
    public int MaxStack => item != null ? Mathf.Max(1, item.maxStack) : 1;

    public bool IsFull => !IsEmpty && count >= MaxStack;

    /// <summary>How many more of this item the slot can still take (0 when empty or full).</summary>
    public int SpaceLeft => IsEmpty ? 0 : Mathf.Max(0, MaxStack - count);

    public static InventorySlot Empty => new InventorySlot { item = null, count = 0 };

    public static InventorySlot Of(ItemDefinition item, int count)
        => new InventorySlot { item = item, count = item != null ? Mathf.Max(0, count) : 0 };
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Central UI relay — same factory/hub pattern as ResourceManager and PlayerInventory: gameplay
/// systems fire an inbound signal (<see cref="SignalShow"/> / <see cref="SignalHide"/> /
/// <see cref="SignalToggle"/>), the manager routes it to the matching reusable panel, then
/// broadcasts an outbound event (<see cref="OnPanelShown"/> / <see cref="OnPanelHidden"/>).
///
/// Callers never reference a concrete screen — they only know a <see cref="UIPanelId"/> and reach
/// the manager through <see cref="Instance"/>. The manager owns the list of reusable panels and
/// reuses them (show/hide), never instantiating per request.
///
/// One per scene. Runs early (negative execution order) so <see cref="Instance"/> and the registry
/// exist before any caller's Awake/OnEnable.
/// </summary>
[DefaultExecutionOrder(-100)]
public class UIManager : MonoBehaviour
{
    public static UIManager Instance { get; private set; }

    [Tooltip("Log each show/hide signal. Off for production.")]
    [SerializeField] private bool _debugLog = true;

    [Tooltip("Reusable panels managed here. Drop UIPanel components in, or Register at runtime.")]
    [SerializeField] private List<UIPanel> _panels = new();

    private readonly Dictionary<UIPanelId, IUIPanel> _registry = new();

    /// <summary>Raised after a panel is shown. Subscribe with += on startup.</summary>
    public event Action<UIPanelId> OnPanelShown;
    /// <summary>Raised after a panel is hidden. Subscribe with += on startup.</summary>
    public event Action<UIPanelId> OnPanelHidden;

    // ── Signals (inbound) ───────────────────────────────────────────────────────

    /// <summary>Signal: show the panel with this id. No-op (warns) if none is registered.</summary>
    public void SignalShow(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (_debugLog) Debug.Log($"[UIManager] show {id}");
        panel.Show();
        OnPanelShown?.Invoke(id);
    }

    /// <summary>Signal: hide the panel with this id.</summary>
    public void SignalHide(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (_debugLog) Debug.Log($"[UIManager] hide {id}");
        panel.Hide();
        OnPanelHidden?.Invoke(id);
    }

    /// <summary>Signal: toggle the panel's visibility.</summary>
    public void SignalToggle(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (panel.IsVisible) SignalHide(id);
        else SignalShow(id);
    }

    public bool IsVisible(UIPanelId id) => TryGet(id, out IUIPanel p, warn: false) && p.IsVisible;

    // ── Registration ──────────────────────────────────────────────────────────

    /// <summary>Register a panel at runtime (panels in the serialized list register automatically).</summary>
    public void Register(IUIPanel panel)
    {
        if (panel == null || panel.PanelId == UIPanelId.None) return;
        _registry[panel.PanelId] = panel;
    }

    public void Unregister(IUIPanel panel)
    {
        if (panel == null) return;
        if (_registry.TryGetValue(panel.PanelId, out IUIPanel existing) && existing == panel)
            _registry.Remove(panel.PanelId);
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[UIManager] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;

        foreach (UIPanel panel in _panels)
        {
            if (panel == null) continue;
            if (panel.PanelId == UIPanelId.None)
            {
                Debug.LogWarning($"[UIManager] '{panel.name}' has PanelId.None; skipped.", panel);
                continue;
            }
            Register(panel);
        }
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private bool TryGet(UIPanelId id, out IUIPanel panel, bool warn = true)
    {
        if (_registry.TryGetValue(id, out panel) && panel != null) return true;
        if (warn) Debug.LogWarning($"[UIManager] No panel registered for {id}.", this);
        return false;
    }
}

using UnityEngine;

/// <summary>
/// Stable identity for a reusable UI screen/widget. Enum instead of a string key so routing
/// through <see cref="UIManager"/> has no magic strings and shows up in the Inspector as a dropdown.
/// Extend as screens are added.
/// </summary>
public enum UIPanelId
{
    None = 0,
    Hud,
    Inventory,
    Dialogue,
    Pause,
    InteractTag,
    ResourceHP,
}

/// <summary>
/// A reusable UI component the <see cref="UIManager"/> can show/hide by <see cref="UIPanelId"/>.
/// Implemented as an interface so the manager never depends on a concrete screen type.
/// </summary>
public interface IUIPanel
{
    UIPanelId PanelId { get; }
    bool IsVisible { get; }
    void Show();
    void Hide();
}

/// <summary>
/// Base class for reusable UI screens driven by <see cref="UIManager"/>. Default Show/Hide just
/// toggles the GameObject; override <see cref="OnShow"/> / <see cref="OnHide"/> for animation,
/// data binding, focus, etc. A concrete screen (e.g. an inventory panel) extends this, picks its
/// <see cref="UIPanelId"/> in the Inspector, and gets registered with the manager — either by
/// being dropped into the manager's serialized list, or via runtime <see cref="UIManager.Register"/>.
/// </summary>
public abstract class UIPanel : MonoBehaviour, IUIPanel
{
    [SerializeField] private UIPanelId _panelId = UIPanelId.None;

    public UIPanelId PanelId => _panelId;
    public bool IsVisible { get; protected set; }

    public virtual void Show()
    {
        if (IsVisible) return;
        gameObject.SetActive(true);
        IsVisible = true;
        OnShow();
    }

    public virtual void Hide()
    {
        if (!IsVisible) return;
        OnHide();
        IsVisible = false;
        gameObject.SetActive(false);
    }

    /// <summary>Called after the panel becomes visible. Bind data / play intro here.</summary>
    protected virtual void OnShow() { }

    /// <summary>Called before the panel hides. Clean up / play outro here.</summary>
    protected virtual void OnHide() { }
}

using UnityEngine;
using UnityEngine.UIElements;

/// <summary>
/// Base for UI Toolkit panels driven by <see cref="UIManager"/>. Wraps the one fragile part of
/// UI Toolkit — element binding — in the proven defense: the visual tree may not exist during
/// OnEnable (component order isn't guaranteed), so <see cref="Bind"/> is retried from Update until
/// it succeeds. Subclasses query/cache elements in Bind and never touch the tree before it's ready.
///
/// Show/Hide toggle the root's <c>display</c> instead of the GameObject, so the UIDocument stays
/// alive and we never rebuild + rebind the tree on every show (which is what made the old HUD
/// flaky). The GameObject itself stays active.
/// </summary>
[RequireComponent(typeof(UIDocument))]
public abstract class UIToolkitPanel : UIPanel
{
    [Tooltip("Visible as soon as it binds (always-present HUD = true; pop-ups like the hover tag = false).")]
    [SerializeField] private bool _startVisible = true;

    protected UIDocument Document { get; private set; }
    protected VisualElement Root { get; private set; }

    private bool _bound;

    // ── Unity messages ────────────────────────────────────────────────────────

    protected virtual void Awake()
    {
        Document = GetComponent<UIDocument>();
        IsVisible = _startVisible;
    }

    protected virtual void OnEnable()
    {
        _bound = false;
        TryBind();
    }

    protected virtual void Update()
    {
        if (!_bound) TryBind();
    }

    // ── Show / hide (display toggle, document stays alive) ──────────────────────

    public override void Show()
    {
        IsVisible = true;
        ApplyDisplay();
        OnShow();
    }

    public override void Hide()
    {
        IsVisible = false;
        ApplyDisplay();
        OnHide();
    }

    // ── Binding ─────────────────────────────────────────────────────────────────

    /// <summary>Query and cache elements. Return false if the tree isn't built yet (retried next frame).</summary>
    protected abstract bool Bind(VisualElement root);

    /// <summary>Called once after a successful bind — do the first data refresh here.</summary>
    protected virtual void OnBound() { }

    private void TryBind()
    {
        if (Document == null) return;
        VisualElement root = Document.rootVisualElement;
        if (root == null) return;
        if (!Bind(root)) return; // sentinel element missing → tree not ready, try again next frame

        Root = root;
        _bound = true;
        ApplyDisplay();
        OnBound();
    }

    private void ApplyDisplay()
    {
        if (Root != null)
            Root.style.display = IsVisible ? DisplayStyle.Flex : DisplayStyle.None;
    }
}

using UnityEngine;
using UnityEngine.UIElements;
using Flynn.Events;

/// <summary>
/// The always-present player HUD as a single UI Toolkit panel: hotbar, echo-shard counter and the
/// robot battery gauge. A thin controller — the layout lives in PlayerHud.uxml/.uss, this only binds
/// elements and pushes values when the source data raises an event (no polling).
///
/// Driven by: <see cref="PlayerInventory"/> (hotbar), an <see cref="IntVariable"/> for echo shards
/// and an <see cref="IntVariable"/> (0–100) for the battery. Registered with <see cref="UIManager"/>
/// as <see cref="UIPanelId.Hud"/>; left visible the whole game.
/// </summary>
public class PlayerHudPanel : UIToolkitPanel
{
    [Header("Sources (echo/battery are asset refs; inventory falls back to Instance)")]
    [SerializeField] private PlayerInventory _inventory;
    [SerializeField] private IntVariable _echoShards;
    [SerializeField] private IntVariable _battery; // 0..100

    private readonly VisualElement[] _slots = new VisualElement[InventoryData.SlotCount];
    private readonly VisualElement[] _icons = new VisualElement[InventoryData.SlotCount];
    private readonly Label[] _counts = new Label[InventoryData.SlotCount];

    private Label _echoLabel;
    private VisualElement _batteryFill;
    private Label _batteryLabel;

    // ── Unity messages ────────────────────────────────────────────────────────

    protected override void OnEnable()
    {
        base.OnEnable();

        if (_inventory == null) _inventory = PlayerInventory.Instance;
        if (_inventory != null)
        {
            _inventory.OnSlotChanged       += RefreshSlot;
            _inventory.OnActiveSlotChanged += RefreshActiveSlot;
        }
        if (_echoShards != null) _echoShards.OnChanged += SetEcho;
        if (_battery    != null) _battery.OnChanged    += SetBattery;

        // Also subscribe to GameEventBus for currency collection feedback
        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Subscribe<CurrencyCollected>(OnCurrencyCollected);
    }

    private void OnDisable()
    {
        if (_inventory != null)
        {
            _inventory.OnSlotChanged       -= RefreshSlot;
            _inventory.OnActiveSlotChanged -= RefreshActiveSlot;
        }
        if (_echoShards != null) _echoShards.OnChanged -= SetEcho;
        if (_battery    != null) _battery.OnChanged    -= SetBattery;

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Unsubscribe<CurrencyCollected>(OnCurrencyCollected);
    }

    // ── Binding ─────────────────────────────────────────────────────────────────

    protected override bool Bind(VisualElement root)
    {
        if (root.Q<VisualElement>("Slot_0") == null) return false; // tree not ready yet

        for (int i = 0; i < InventoryData.SlotCount; i++)
        {
            _slots[i]  = root.Q<VisualElement>($"Slot_{i}");
            _icons[i]  = root.Q<VisualElement>($"Icon_{i}");
            _counts[i] = root.Q<Label>($"Count_{i}");
        }
        _echoLabel    = root.Q<Label>("EchoCount");
        _batteryFill  = root.Q<VisualElement>("BatteryFill");
        _batteryLabel = root.Q<Label>("BatteryLabel");
        return true;
    }

    protected override void OnBound()
    {
        RefreshAll();
        if (_echoShards != null) SetEcho(_echoShards.Value);
        if (_battery    != null) SetBattery(_battery.Value);
    }

    // ── Refresh (event-driven) ──────────────────────────────────────────────────

    private void RefreshAll()
    {
        if (Root == null || _inventory == null) return;
        for (int i = 0; i < InventoryData.SlotCount && i < _inventory.SlotCount; i++) RefreshSlot(i);
        RefreshActiveSlot(_inventory.ActiveSlotIndex);
    }

    private void RefreshSlot(int i)
    {
        if (Root == null || i < 0 || i >= InventoryData.SlotCount) return;
        if (_icons[i] == null) return;

        InventorySlot slot = _inventory.GetSlot(i);
        bool hasItem = !slot.IsEmpty;

        if (hasItem && slot.item.icon != null)
        {
            _icons[i].style.backgroundImage = new StyleBackground(slot.item.icon);
            _icons[i].style.display = DisplayStyle.Flex;
        }
        else
        {
            _icons[i].style.backgroundImage = StyleKeyword.None;
            _icons[i].style.display = DisplayStyle.None;
        }

        if (_counts[i] != null)
        {
            bool show = hasItem && slot.count > 1;
            _counts[i].text = show ? slot.count.ToString() : string.Empty;
            _counts[i].style.display = show ? DisplayStyle.Flex : DisplayStyle.None;
        }
    }

    private void RefreshActiveSlot(int active)
    {
        if (Root == null) return;
        for (int i = 0; i < InventoryData.SlotCount; i++)
        {
            if (_slots[i] == null) continue;
            if (i == active) _slots[i].AddToClassList("hotbar-slot--active");
            else             _slots[i].RemoveFromClassList("hotbar-slot--active");
        }
    }

    private void SetEcho(int value)
    {
        if (_echoLabel != null) _echoLabel.text = value.ToString();
    }

    private void SetBattery(int value)
    {
        int pct = Mathf.Clamp(value, 0, 100);
        if (_batteryFill != null) _batteryFill.style.width = new StyleLength(Length.Percent(pct));
        if (_batteryLabel != null) _batteryLabel.text = pct + "%";
    }

    private void OnCurrencyCollected(CurrencyCollected evt)
    {
        // The IntVariable already drives SetEcho via OnChanged, but this gives us
        // a hook for future sparkle animations / sound triggers at the HUD level.
    }
}

