using UnityEngine;
using Flynn.Events;

/// <summary>
/// Robot energy system. Owns a 0–100 <see cref="IntVariable"/> battery and drains it
/// both passively (over time) and actively (from gameplay actions via <see cref="BatterySettings"/>).
/// The HUD reads the battery purely through <see cref="IntVariable.OnChanged"/>.
///
/// Supports a configurable <see cref="BatterySettings"/> SO for action costs and an
/// <c>infiniteBatteryDebug</c> toggle for sandbox testing without battery interference.
/// </summary>
[DefaultExecutionOrder(-40)]
public class RobotBattery : MonoBehaviour
{
    public const int Min = 0;
    public const int Max = 100;

    public static RobotBattery Instance { get; private set; }

    [Tooltip("The shared 0–100 battery value the HUD displays. Assign the same asset on PlayerHudPanel.")]
    [SerializeField] private IntVariable _battery;

    [Tooltip("Battery settings: action costs, passive drain, debug mode.")]
    [SerializeField] private BatterySettings _settings;

    [SerializeField, Range(Min, Max)] private int _startCharge = 100;

    [Tooltip("Passive drain in battery points per second. Overridden by BatterySettings if assigned.")]
    [SerializeField] private float _drainPerSecond = 1f;

    [SerializeField] private bool _autoDrain = true;

    private float _accum;

    // ── API ──────────────────────────────────────────────────────────────────

    public int Charge => _battery != null ? _battery.Value : 0;
    public bool IsEmpty => Charge <= Min;
    public bool IsFull  => Charge >= Max;

    /// <summary>Whether infinite battery debug mode is active.</summary>
    public bool InfiniteDebug => _settings != null && _settings.infiniteBatteryDebug;

    /// <summary>Access to battery settings for cost lookups (read-only).</summary>
    public BatterySettings Settings => _settings;

    /// <summary>
    /// Can the battery afford this cost? Returns true if infinite debug is on,
    /// or if there's enough charge (as a float, so partial charges are possible).
    /// </summary>
    public bool CanSpend(float cost)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return true;
        return Charge >= cost;
    }

    /// <summary>
    /// Spend a float amount of battery (for action costs). No-op in infinite debug mode.
    /// Publishes <see cref="BatteryChanged"/> and threshold events.
    /// </summary>
    public void Spend(float cost)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return;
        if (cost <= 0f) return;
        _accum -= cost;
        FlushAccum();
    }

    /// <summary>Drain over time (continuous actions like pulling/scanning).</summary>
    public void DrainOverTime(float costPerSecond)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return;
        _accum -= costPerSecond * Time.deltaTime;
        FlushAccum();
    }

    /// <summary>Add charge (negative to drain). Clamped to 0–100; notifies via the IntVariable.</summary>
    public void AddCharge(int amount) => SetCharge(Charge + amount);

    /// <summary>Drain charge by a positive amount.</summary>
    public void Drain(int amount) => SetCharge(Charge - Mathf.Abs(amount));

    public void SetCharge(int value)
    {
        if (_battery == null) return;
        int prev = Charge;
        _battery.Value = Mathf.Clamp(value, Min, Max);
        int current = Charge;

        if (GameEventBus.Instance != null)
        {
            GameEventBus.Instance.Publish(new BatteryChanged(current, Max));
            if (current <= Min && prev > Min)
                GameEventBus.Instance.Publish(new BatteryEmpty());
            else if (current <= LowThreshold && prev > LowThreshold)
                GameEventBus.Instance.Publish(new BatteryLow(current, (float)current / Max));
        }
    }

    public void SetAutoDrain(bool on) => _autoDrain = on;

    private int LowThreshold => _settings != null ? _settings.lowBatteryThreshold : 20;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[RobotBattery] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        SetCharge(_startCharge);
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (!_autoDrain || _battery == null || IsEmpty) return;

        float drainRate = _settings != null && _settings.enablePassiveDrain
            ? _settings.passiveDrainPerSecond
            : _drainPerSecond;

        if (drainRate <= 0f) return;

        _accum -= drainRate * Time.deltaTime;
        FlushAccum();
    }

    /// <summary>Flush accumulated fractional drain to the integer battery value.</summary>
    private void FlushAccum()
    {
        if (_accum >= 0f) return;
        int whole = Mathf.FloorToInt(-_accum);
        if (whole <= 0) return;
        _accum += whole;
        Drain(whole);
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Left-click swing for the wrench multitool. Simple tap with a short cooldown
/// to prevent spam. The swing faces the mouse aim point. Routes damage through
/// the ResourceManager observer pattern. Disabled while the wrench is airborne (thrown).
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchSwingController : MonoBehaviour
{
    private const int WrenchAnimIndex = 4;

    [SerializeField] private WrenchConfig _config;
    [Tooltip("Optional — used to block swinging while the wrench is mid-throw.")]
    [SerializeField] private WrenchThrowController _throw;

    [Tooltip("Directional swipe arc visual. Fed the player→mouse direction on each swing.")]
    [SerializeField] private WrenchSwingArc _swingArc;

    [Tooltip("Cooldown between swings (seconds).")]
    [SerializeField] private float _cooldownTime = 0.1f;

    private PlayerMouseAimer _aimer;
    private PlayerInitializer _playerInit;
    private IPlayerVisual _animDriver;
    private RobotBattery _battery;
    private float _cooldown;

    public bool IsCharging => false;
    public float ChargeNormalized => 0f;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _playerInit = GetComponent<PlayerInitializer>();
        _battery    = RobotBattery.Instance;
    }

    private void Update()
    {
        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable) return;

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
            DoSwing();
    }

    private void DoSwing()
    {
        // Battery cost check
        float swingCost = _battery != null && _battery.Settings != null
            ? _battery.Settings.swingCost : 0f;
        if (_battery != null && !_battery.CanSpend(swingCost)) return;

        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);

        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float speed = _config != null ? _config.lightSwingAnimSpeed : 1.0f;
        if (_animDriver != null)
            _animDriver.ReleaseSwing(animIndex, speed);

        if (_swingArc != null)
            _swingArc.Play(_aimer.WorldAimPoint);

        _cooldown = _cooldownTime;

        // Route hit through the ResourceManager observer pattern.
        int damage = _config != null ? _config.lightSwingDamage : 1;
        GameObject target = _aimer.HoveredGameObject;
        if (_playerInit != null && damage > 0)
            _playerInit.EmitHit(_aimer.WorldAimPoint, target, damage);

        // Publish swing event
        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;
        PublishEvent(new ToolSwingStarted(tool, _aimer.WorldAimPoint));

        // Spend battery after successful swing
        if (_battery != null && swingCost > 0f) _battery.Spend(swingCost);
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;

/// <summary>
/// Placeholder wrench swing VFX: a slash line that draws from the player toward
/// the hit point, plus an expanding ring at the endpoint. Both fade out.
/// Will be swapped for real sprite anims later.
/// </summary>
[RequireComponent(typeof(LineRenderer))]
public class WrenchSwingArc : MonoBehaviour
{
    [Header("Slash Line")]
    [SerializeField] private float _slashDrawTime = 0.1f;
    [SerializeField] private float _slashFadeTime = 0.15f;
    [SerializeField] private float _slashWidth = 0.1f;

    [Header("Impact Ring")]
    [SerializeField] private float _ringMaxRadius = 0.5f;
    [SerializeField] private float _ringExpandTime = 0.1f;
    [SerializeField] private float _ringFadeTime = 0.2f;
    [SerializeField] private int _ringSegments = 24;

    [Header("Common")]
    [SerializeField] private float _arcHeight = 0.8f;
    [SerializeField] private Color _slashColor = new Color(1f, 0.9f, 0.6f);
    [SerializeField] private Color _ringColor = new Color(1f, 0.7f, 0.3f);

    private LineRenderer _slashLr;
    private LineRenderer _ringLr;
    private bool _playing;
    private float _timer;
    private Vector3 _startPos;
    private Vector3 _hitPos;

    private void Awake()
    {
        // Slash LineRenderer is configured in the inspector — only set runtime properties
        _slashLr = GetComponent<LineRenderer>();
        _slashLr.useWorldSpace = true;
        _slashLr.positionCount = 0;
        _slashLr.enabled = false;

        // Ring is created at runtime — needs full setup
        var ringGo = new GameObject("Ring");
        ringGo.transform.SetParent(transform, false);
        _ringLr = ringGo.AddComponent<LineRenderer>();
        _ringLr.useWorldSpace = true;
        _ringLr.startWidth = _slashWidth * 0.6f;
        _ringLr.endWidth = _slashWidth * 0.2f;
        _ringLr.positionCount = 0;
        _ringLr.enabled = false;
        _ringLr.numCornerVertices = 4;
        _ringLr.numCapVertices = 4;
        _ringLr.loop = false;
        _ringLr.material = new Material(Shader.Find("Sprites/Default"));

        HideAll();
    }

    public void Play(Vector3 worldAimPoint)
    {
        _startPos = transform.position + Vector3.up * _arcHeight;
        _hitPos = worldAimPoint;

        _timer = 0f;
        _playing = true;
    }

    private void Update()
    {
        if (!_playing) return;

        _timer += Time.deltaTime;

        float slashTotal = _slashDrawTime + _slashFadeTime;
        float ringTotal = _ringExpandTime + _ringFadeTime;
        float total = Mathf.Max(slashTotal, ringTotal);

        if (_timer >= total)
        {
            _playing = false;
            HideAll();
            return;
        }

        UpdateSlash();
        UpdateRing();
    }

    private void UpdateSlash()
    {
        float drawT = Mathf.Clamp01(_timer / _slashDrawTime);

        float alpha = _timer <= _slashDrawTime
            ? 1f
            : Mathf.Clamp01(1f - (_timer - _slashDrawTime) / _slashFadeTime);

        if (alpha <= 0f) { _slashLr.enabled = false; return; }

        Vector3 tip = Vector3.Lerp(_startPos, _hitPos, drawT);
        _slashLr.enabled = true;
        _slashLr.positionCount = 2;
        _slashLr.SetPosition(0, _startPos);
        _slashLr.SetPosition(1, tip);

        Color c = _slashColor;
        _slashLr.startColor = new Color(c.r, c.g, c.b, alpha);
        _slashLr.endColor = new Color(c.r, c.g, c.b, alpha * 0.3f);
    }

    private void UpdateRing()
    {
        float ringStart = _slashDrawTime * 0.5f;
        float localT = _timer - ringStart;
        if (localT < 0f) { _ringLr.enabled = false; return; }

        float expandT = Mathf.Clamp01(localT / _ringExpandTime);

        float alpha = localT <= _ringExpandTime
            ? 1f
            : Mathf.Clamp01(1f - (localT - _ringExpandTime) / _ringFadeTime);

        if (alpha <= 0f) { _ringLr.enabled = false; return; }

        float radius = Mathf.Lerp(0.05f, _ringMaxRadius, expandT);

        _ringLr.enabled = true;
        _ringLr.positionCount = _ringSegments + 1;
        for (int i = 0; i <= _ringSegments; i++)
        {
            float angle = (i / (float)_ringSegments) * Mathf.PI * 2f;
            Vector3 offset = new Vector3(Mathf.Cos(angle) * radius, 0f, Mathf.Sin(angle) * radius);
            _ringLr.SetPosition(i, _hitPos + offset);
        }

        Color c = _ringColor;
        _ringLr.startColor = new Color(c.r, c.g, c.b, alpha);
        _ringLr.endColor = new Color(c.r, c.g, c.b, alpha * 0.5f);
    }

    private void HideAll()
    {
        _slashLr.enabled = false;
        _ringLr.enabled = false;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Right-click throw for the wrench. Tap = short throw; hold to charge for a longer
/// throw (distance scales min→max with charge). Spawns a ThrownWrench projectile that
/// flies to the target, hovers, then boomerangs back to the player and is caught.
/// Only one throw may be airborne at a time. Exposes IsCharging / ChargeNormalized /
/// IsAirborne for the aim reticle and the swing controller.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchThrowController : MonoBehaviour
{
    [SerializeField] private WrenchConfig _config;
    [SerializeField] private GameObject _thrownWrenchPrefab;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private ThrownWrench _airborne;
    private float _chargeTimer;
    private bool _charging;

    public bool IsCharging => _charging;
    public bool IsAirborne => _airborne != null;
    public float ChargeNormalized => _config != null && _config.throwChargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.throwChargeTime)
        : 0f;

    /// <summary>
    /// World-space hand position: the billboard visual centre, so the wrench
    /// appears to leave from and return to the sprite rather than the physics root.
    /// </summary>
    public Vector3 CatchPoint =>
        _animDriver != null ? _animDriver.VisualCenter : transform.position;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
    }

    private void Update()
    {
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !IsAirborne;
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetMouseButtonDown(1))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetMouseButton(1))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetMouseButtonUp(1))
        {
            DoThrow();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void DoThrow()
    {
        // Battery cost check
        var battery = RobotBattery.Instance;
        float throwCost = battery != null && battery.Settings != null
            ? battery.Settings.throwCost : 0f;
        if (battery != null && !battery.CanSpend(throwCost)) return;

        if (_thrownWrenchPrefab == null || _config == null) return;

        // Use the billboard's visual centre as origin so distance/direction is
        // measured from where the sprite appears on screen, not from the feet.
        Vector3 origin = CatchPoint;

        // Direction on the XZ plane from the visual centre to the aim point.
        Vector3 toAim = _aimer.WorldAimPoint - origin;
        toAim.y = 0f;
        if (toAim.sqrMagnitude < 0.0001f) toAim = transform.forward;

        // Charge gates maximum reach. If the cursor is closer than that, the wrench
        // lands exactly on it; if farther, it stops at the charge-limited range.
        float maxDist = Mathf.Lerp(_config.minThrowDistance, _config.maxThrowDistance, ChargeNormalized);
        float dist = Mathf.Min(toAim.magnitude, maxDist);

        Vector3 target = origin + toAim.normalized * dist;
        // Restore the aim Y so the wrench lands at the actual world surface height.
        target.y = _aimer.WorldAimPoint.y;

        GameObject go = Instantiate(_thrownWrenchPrefab, CatchPoint, Quaternion.identity);
        _airborne = go.GetComponent<ThrownWrench>();
        if (_airborne != null) _airborne.Launch(this, target, _config);
        else Destroy(go);

        // Spend battery after successful throw
        if (battery != null && throwCost > 0f) battery.Spend(throwCost);

        // Publish throw events
        if (GameEventBus.Instance != null)
        {
            GameEventBus.Instance.Publish(new ToolThrowReleased(target, ChargeNormalized));
        }
    }

    /// <summary>Called by ThrownWrench when it has returned and been caught.</summary>
    public void OnCaught() => _airborne = null;
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Projectile spawned by WrenchThrowController. Flies outbound to a target point,
/// hovers (returnDelay), then homes back to the thrower like a boomerang and is caught.
/// Spins a child visual for the boomerang look. On impact with a ResourceNode,
/// applies throw damage through the effectiveness system.
/// </summary>
public class ThrownWrench : MonoBehaviour
{
    private enum Phase { Outbound, Hover, Returning }

    private WrenchThrowController _owner;
    private WrenchConfig _config;
    private Vector3 _target;
    private Phase _phase;
    private float _hoverTimer;
    private Transform _spin;
    private Camera _cam;
    private float _roll;
    private bool _hasHitTarget;

    public void Launch(WrenchThrowController owner, Vector3 target, WrenchConfig config)
    {
        _owner   = owner;
        _target  = target;
        _config  = config;
        _phase   = Phase.Outbound;
        _spin    = transform.childCount > 0 ? transform.GetChild(0) : transform;
    }

    private void Update()
    {
        if (_config == null) return;

        switch (_phase)
        {
            case Phase.Outbound:
                MoveToward(_target, _config.throwSpeed);
                if (Reached(_target, 0.1f))
                {
                    _phase = Phase.Hover;
                    _hoverTimer = _config.returnDelay;
                }
                break;

            case Phase.Hover:
                _hoverTimer -= Time.deltaTime;
                if (_hoverTimer <= 0f) _phase = Phase.Returning;
                break;

            case Phase.Returning:
                Vector3 catchPoint = _owner != null ? _owner.CatchPoint : transform.position;
                MoveToward(catchPoint, _config.returnSpeed);
                if (Reached(catchPoint, _config.catchRadius))
                {
                    if (_owner != null) _owner.OnCaught();
                    Destroy(gameObject);
                }
                break;
        }
    }

    /// <summary>
    /// Detect collision with ResourceNodes during the outbound phase.
    /// Uses the effectiveness system to determine damage.
    /// </summary>
    private void OnCollisionEnter(Collision collision)
    {
        if (_phase != Phase.Outbound || _hasHitTarget) return;

        ResourceNode node = collision.gameObject.GetComponentInParent<ResourceNode>();
        if (node == null) return;

        _hasHitTarget = true;

        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;

        int damage = _config != null ? _config.heavySwingDamage : 2;
        Vector3 hitDir = (collision.transform.position - transform.position).normalized;

        var hit = new ToolHitContext(
            source: gameObject,
            toolType: tool,
            action: ToolActionType.Throw,
            damage: damage,
            hitPoint: collision.contacts.Length > 0 ? collision.contacts[0].point : transform.position,
            hitDirection: hitDir,
            charge: 1f
        );

        node.TryApplyToolHit(hit);

        // Immediately start returning after impact
        _phase = Phase.Returning;
    }

    // Billboard the visual to the camera (like the player sprite) and spin it in the
    // screen plane so the boomerang reads as rotating regardless of view angle.
    private void LateUpdate()
    {
        if (_config == null || _spin == null) return;
        if (_cam == null) _cam = Camera.main;
        if (_cam == null) return;

        _roll += _config.spinSpeed * Time.deltaTime;
        _spin.rotation = _cam.transform.rotation * Quaternion.Euler(0f, 0f, _roll);
    }

    private void MoveToward(Vector3 p, float speed)
        => transform.position = Vector3.MoveTowards(transform.position, p, speed * Time.deltaTime);

    private bool Reached(Vector3 p, float radius)
        => (transform.position - p).sqrMagnitude <= radius * radius;
}

using System.Collections.Generic;
using UnityEngine;
using Flynn.Events;

/// <summary>
/// Scene-level manager for audio SFX. Maintains a pool of AudioSource components
/// for one-shot playback. Subscribes to GameEventBus events and logs debug messages
/// for now. Actual AudioClip playback will be added later.
/// One per scene on the MANAGERS GameObject. NOT a singleton.
/// </summary>
public class AudioManager : MonoBehaviour
{
    [Tooltip("Number of pooled AudioSource instances for one-shot SFX.")]
    [SerializeField] private int _poolSize = 3;

    private readonly List<AudioSource> _sources = new();

    // ── Unity messages ──────────────────────────────────────────────────────

    private void Awake()
    {
        for (int i = 0; i < _poolSize; i++)
        {
            var source = gameObject.AddComponent<AudioSource>();
            source.playOnAwake = false;
            _sources.Add(source);
        }
    }

    private void OnEnable()
    {
        GameEventBus.Instance.Subscribe<ResourceDamaged>(OnResourceDamaged);
        GameEventBus.Instance.Subscribe<ResourceDepleted>(OnResourceDepleted);
        GameEventBus.Instance.Subscribe<ToolSwingStarted>(OnToolSwingStarted);
        GameEventBus.Instance.Subscribe<ToolHitTarget>(OnToolHitTarget);
        GameEventBus.Instance.Subscribe<ItemPickedUp>(OnItemPickedUp);
        GameEventBus.Instance.Subscribe<RopeGrappleStarted>(OnRopeGrappleStarted);
        GameEventBus.Instance.Subscribe<BatteryLow>(OnBatteryLow);
        GameEventBus.Instance.Subscribe<BatteryEmpty>(OnBatteryEmpty);
    }

    private void OnDisable()
    {
        if (GameEventBus.Instance == null) return;
        GameEventBus.Instance.Unsubscribe<ResourceDamaged>(OnResourceDamaged);
        GameEventBus.Instance.Unsubscribe<ResourceDepleted>(OnResourceDepleted);
        GameEventBus.Instance.Unsubscribe<ToolSwingStarted>(OnToolSwingStarted);
        GameEventBus.Instance.Unsubscribe<ToolHitTarget>(OnToolHitTarget);
        GameEventBus.Instance.Unsubscribe<ItemPickedUp>(OnItemPickedUp);
        GameEventBus.Instance.Unsubscribe<RopeGrappleStarted>(OnRopeGrappleStarted);
        GameEventBus.Instance.Unsubscribe<BatteryLow>(OnBatteryLow);
        GameEventBus.Instance.Unsubscribe<BatteryEmpty>(OnBatteryEmpty);
    }

    // ── Event handlers ──────────────────────────────────────────────────────

    private void OnResourceDamaged(ResourceDamaged evt)
    {
        Debug.Log($"[AudioManager] Play hit sound at {evt.Position}");
    }

    private void OnResourceDepleted(ResourceDepleted evt)
    {
        Debug.Log($"[AudioManager] Play break sound at {evt.Position}");
    }

    private void OnToolSwingStarted(ToolSwingStarted evt)
    {
        Debug.Log($"[AudioManager] Play swing whoosh \u2014 tool {evt.ToolType}");
    }

    private void OnToolHitTarget(ToolHitTarget evt)
    {
        Debug.Log($"[AudioManager] Play impact sound at {evt.Hit.HitPoint}");
    }

