/// One asset lives in Configs/Player/. Referenced by the wrench controllers and
/// the aim reticle so all wrench feel is data-driven in one place.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Wrench Config", fileName = "WrenchConfig")]
public class WrenchConfig : ScriptableObject
{
    [Header("Swing (Left Click)")]
    [Tooltip("Seconds of hold to reach a full-power (heavy) swing.")]
    public float swingChargeTime = 1.2f;
    [Tooltip("Charge fraction (0-1) at/above which a swing counts as heavy.")]
    [Range(0f, 1f)] public float heavySwingThreshold = 0.6f;
    public float lightSwingCooldown = 0.45f;
    public float heavySwingCooldown = 0.8f;

    [Tooltip("Release playback speed for a zero-charge (light) swing.")]
    [Min(0.1f)] public float lightSwingAnimSpeed = 1.0f;
    [Tooltip("Release playback speed for a full-charge (heavy) swing — fast follow-through, the stored power releasing. Release speed lerps light→heavy by charge.")]
    [Min(0.1f)] public float heavySwingAnimSpeed = 2.5f;

    [Header("Harvest Damage")]
    [Tooltip("Damage points applied to a ResourceNode on a light swing.")]
    [Min(1)] public int lightSwingDamage = 1;
    [Tooltip("Damage points applied to a ResourceNode on a heavy swing.")]
    [Min(1)] public int heavySwingDamage = 2;

    [Header("Throw (Right Click)")]
    [Tooltip("Seconds of hold to reach max throw distance.")]
    public float throwChargeTime = 0.8f;
    public float minThrowDistance = 3f;
    public float maxThrowDistance = 9f;
    [Tooltip("Outbound travel speed (units/sec).")]
    public float throwSpeed = 12f;
    [Tooltip("Visual spin speed of the thrown wrench (deg/sec).")]
    public float spinSpeed = 720f;
    [Tooltip("Seconds the wrench hovers at the apex before boomeranging back.")]
    public float returnDelay = 0.4f;
    [Tooltip("Homing speed on the return leg (units/sec).")]
    public float returnSpeed = 14f;
    [Tooltip("Distance to the catch point at which a returning wrench is caught.")]
    public float catchRadius = 0.6f;
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Wrench grapple with swing physics. Hold Q to charge, release to fire.
/// A hook projectile travels from the player's visual center to the target,
/// then the player swings on the rope with pendulum physics (momentum preservation
/// on release). Grapples what the cursor is over (resolved by PlayerMouseAimer):
///   - RopeAnchor → swing the player around the anchor point
///   - RopePullable → reel the object toward the player
/// Blocked while on mud. Requires the wrench as the active item.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class RopeLassoController : MonoBehaviour
{
    [SerializeField] private RopeLassoConfig _config;
    [Tooltip("Rope visual. A child LineRenderer; enabled only while grappling.")]
    [SerializeField] private LineRenderer _ropeLine;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private SolarpunkCharacterController _controller;
    private TerrainStateAggregator _terrainState;
    private Rigidbody _rb;
    private PlayerCarryController _carry;

    // ── Charge ──────────────────────────────────────────────────────────────

    private float _chargeTimer;
    private bool _charging;

    // ── State machine ───────────────────────────────────────────────────────

    private enum GrappleState { Idle, Firing, Swinging, PullingObject }
    private GrappleState _state = GrappleState.Idle;

    // Firing state
    private Vector3 _fireStart;
    private Vector3 _fireTarget;
    private float _fireElapsed;

    // Swing state
    private Vector3 _anchorPoint;
    private float _ropeLength;
    private float _swingElapsed;

    // Pull state
    private Rigidbody _pullBody;
    private float _pullElapsed;

    // Rope visual
    private const int RopeSegments = 10;
    private Vector3[] _ropePoints;

    // Cached for end-event publishing
    private RopeAnchor _activeAnchor;
    private RopePullable _activePullable;

    // Actual world-space anchor (for visual), separate from the Y-projected _anchorPoint
    private Vector3 _anchorWorldPos;

    // ── Public API ──────────────────────────────────────────────────────────

    public bool IsCharging => _charging;
    public float ChargeNormalized => _config != null && _config.chargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.chargeTime) : 0f;
    public bool IsPulling => _state == GrappleState.Swinging || _state == GrappleState.PullingObject;
    public bool IsSwinging => _state == GrappleState.Swinging;

    /// <summary>
    /// Billboard visual centre — the rope leaves from the sprite's centre, not the feet.
    /// Uses the IPlayerVisual.VisualCenter which accounts for camera-tilt offset on
    /// the billboarded sprite.
    /// </summary>
    public Vector3 HandPoint => _animDriver != null ? _animDriver.VisualCenter : transform.position;

    // ── Awake ───────────────────────────────────────────────────────────────

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _controller = GetComponent<SolarpunkCharacterController>();
        _terrainState = GetComponent<TerrainStateAggregator>();
        _rb         = GetComponent<Rigidbody>();
        _carry      = GetComponent<PlayerCarryController>();

        _ropePoints = new Vector3[RopeSegments];

        if (_ropeLine != null)
        {
            _ropeLine.positionCount = RopeSegments;
            _ropeLine.enabled = false;
        }
    }

    // ── Update: input, charging, firing progress ────────────────────────────

    private void Update()
    {
        switch (_state)
        {
            case GrappleState.Idle:
                UpdateIdle();
                break;
            case GrappleState.Firing:
                UpdateFiring();
                break;
            case GrappleState.Swinging:
                UpdateSwingInput();
                break;
            case GrappleState.PullingObject:
                UpdatePullInput();
                break;
        }
    }

    private void UpdateIdle()
    {
        bool onMud = _terrainState != null
            ? _terrainState.CurrentTerrainState.BlocksRope
            : (_controller != null && !_controller.CanJump);
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !onMud
                      && (_carry == null || !_carry.IsCarrying);
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetKeyDown(KeyCode.Q))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetKey(KeyCode.Q))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetKeyUp(KeyCode.Q))
        {
            FireLasso();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void UpdateFiring()
    {
        _fireElapsed += Time.deltaTime;
        float fireDuration = _config != null ? _config.hookTravelTime : 0.12f;
        float t = Mathf.Clamp01(_fireElapsed / fireDuration);

        // Ease-out for a snappy travel feel
        float easedT = 1f - Mathf.Pow(1f - t, 3f);
        Vector3 hookPos = Vector3.Lerp(_fireStart, _fireTarget, easedT);

        // Draw extending rope from hand to hook tip (sag fades as hook approaches target)
        DrawRope(HandPoint, hookPos, slack: 0.4f * (1f - t));

        if (t >= 1f)
        {
            if (_activePullable != null)
                StartPullingObject();
            else
                StartSwinging();
        }
    }

    private void UpdateSwingInput()
    {
        // Release with Jump or Q
        if (Input.GetButtonDown("Jump") || Input.GetKeyDown(KeyCode.Q))
        {
            EndGrapple(preserveMomentum: true);
            return;
        }

        // Adjust rope length with scroll wheel
        if (_config != null)
        {
            float scroll = Input.mouseScrollDelta.y;
            if (scroll != 0f)
            {
                _ropeLength -= scroll * _config.ropeAdjustSpeed * Time.deltaTime;
                _ropeLength = Mathf.Clamp(_ropeLength, _config.minRopeLength, _config.maxRopeLength);
            }
        }
    }

    private void UpdatePullInput()
    {
        // Release pull with Q
        if (Input.GetKeyUp(KeyCode.Q))
            EndGrapple(preserveMomentum: false);
    }

    // ── Fire ────────────────────────────────────────────────────────────────

    private void FireLasso()
    {
        if (_config == null) return;

        RopeAnchor anchor = _aimer.HoveredAnchor;
        RopePullable pullable = _aimer.HoveredPullable;
        if (anchor == null && pullable == null) return;

        Vector3 grapplePoint = _aimer.HoveredGrapplePoint;
        float dist = Vector3.Distance(HandPoint, grapplePoint);
        if (dist < _config.minRange || dist > _config.maxRange) return;

        // Battery check
        var battery = RobotBattery.Instance;
        float grappleCost = battery != null && battery.Settings != null
            ? battery.Settings.grappleCost : 0f;
        if (battery != null && !battery.CanSpend(grappleCost)) return;
        if (battery != null && grappleCost > 0f) battery.Spend(grappleCost);

        // Cache targets for events
        _activeAnchor = anchor;
        _activePullable = pullable;

        // Start firing
        _state = GrappleState.Firing;
        _fireStart = HandPoint;
        _fireTarget = grapplePoint;
        _fireElapsed = 0f;

        // Face the target
        if (_animDriver != null) _animDriver.FaceWorldDirection(grapplePoint - transform.position);

        // Publish start event immediately
        if (GameEventBus.Instance != null)
        {
            if (pullable != null)
                GameEventBus.Instance.Publish(new RopePullStarted(pullable));
            else if (anchor != null)
                GameEventBus.Instance.Publish(new RopeGrappleStarted(anchor));
        }
    }

    // ── State transitions ───────────────────────────────────────────────────

    private void StartSwinging()
    {
        _state = GrappleState.Swinging;
        _swingElapsed = 0f;

        // 2.5D: project the anchor onto the player's Y so the tether is horizontal-only.
        // The rope constrains on the XZ plane; Y is entirely gravity/jump controlled.
        _anchorPoint = new Vector3(_fireTarget.x, _rb.position.y, _fireTarget.z);
        _anchorWorldPos = _fireTarget;

        // Rope length = initial horizontal distance to anchor
        Vector3 toAnchorXZ = _anchorPoint - _rb.position;
        toAnchorXZ.y = 0f;
        _ropeLength = toAnchorXZ.magnitude;
        if (_config != null)
            _ropeLength = Mathf.Clamp(_ropeLength, _config.minRopeLength, _config.maxRopeLength);

        // Snap impulse toward anchor on XZ only (no vertical yank)
        if (_config != null && _config.snapForce > 0f && _rb != null)
        {
            Vector3 toAnchor = (_anchorPoint - _rb.position);
            toAnchor.y = 0f;
            if (toAnchor.sqrMagnitude > 0.01f)
                _rb.AddForce(toAnchor.normalized * _config.snapForce, ForceMode.Impulse);
        }

        // Suppress character controller so it doesn't fight the swing
        if (_controller != null) _controller.SteeringControl = 0f;
    }

    private void StartPullingObject()
    {
        _state = GrappleState.PullingObject;
        _pullBody = _activePullable != null ? _activePullable.Body : null;
        _pullElapsed = 0f;

        if (_pullBody == null) { EndGrapple(false); return; }
    }

    // ── FixedUpdate: swing & pull physics ────────────────────────────────────

    private void FixedUpdate()
    {
        switch (_state)
        {
            case GrappleState.Swinging:
                UpdateSwingPhysics();
                break;
            case GrappleState.PullingObject:
                UpdatePullPhysics();
                break;
        }
    }

    private void UpdateSwingPhysics()
    {
        if (_rb == null) { EndGrapple(false); return; }

        _swingElapsed += Time.fixedDeltaTime;

        // Safety timeout
        if (_config != null && _swingElapsed >= _config.pullTimeout)
        {
            EndGrapple(true);
            return;
        }

        // Battery drain while swinging
        var battery = RobotBattery.Instance;
        if (battery != null && battery.Settings != null && battery.Settings.pullCostPerSecond > 0f)
        {
            battery.DrainOverTime(battery.Settings.pullCostPerSecond);
            if (battery.IsEmpty) { EndGrapple(true); return; }
        }

        // 2.5D: re-project anchor to player's Y each step so the tether stays horizontal
        // even as the player rises/falls from gravity and jumps.
        _anchorPoint = new Vector3(_anchorPoint.x, _rb.position.y, _anchorPoint.z);

        // Swing input: WASD adds tangential force on the XZ plane to pump the swing
        Vector3 inputDir = new Vector3(
            Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical")).normalized;
        if (inputDir.sqrMagnitude > 0.01f)
        {
            Vector3 toAnchorXZ = (_anchorPoint - _rb.position);
            toAnchorXZ.y = 0f;
            if (toAnchorXZ.sqrMagnitude > 0.001f)
            {
                toAnchorXZ.Normalize();
                // Tangent on XZ: perpendicular to the rope direction
                Vector3 tangent = inputDir - Vector3.Project(inputDir, toAnchorXZ);
                tangent.y = 0f;
                if (tangent.sqrMagnitude > 0.001f)
                {
                    tangent.Normalize();
                    float swingForce = _config != null ? _config.swingForce : 30f;
                    _rb.AddForce(tangent * swingForce, ForceMode.Acceleration);
                }
            }
        }

        // 2.5D: enforce rope length constraint on the XZ plane only.
        // Y is untouched — gravity and jumps work normally while tethered.
        Vector3 toAnchorVec = _anchorPoint - _rb.position;
        toAnchorVec.y = 0f;
        float currentDistXZ = toAnchorVec.magnitude;

        if (currentDistXZ > _ropeLength && currentDistXZ > 0.001f)
        {
            Vector3 dirXZ = toAnchorVec.normalized;

            // Correct XZ position to stay on the horizontal rope circle
            Vector3 corrected = _rb.position;
            corrected.x = _anchorPoint.x - dirXZ.x * _ropeLength;
            corrected.z = _anchorPoint.z - dirXZ.z * _ropeLength;
            _rb.position = corrected;

            // Remove outward radial XZ velocity (keep tangential + all Y velocity)
            Vector3 outwardXZ = new Vector3(-dirXZ.x, 0f, -dirXZ.z);
            float vOut = Vector3.Dot(new Vector3(_rb.velocity.x, 0f, _rb.velocity.z), outwardXZ);
            if (vOut > 0f)
            {
                Vector3 correction = outwardXZ * vOut;
                _rb.velocity -= correction;
            }

            // Cap XZ swing speed only (Y is free)
            Vector3 velXZ = new Vector3(_rb.velocity.x, 0f, _rb.velocity.z);
            if (_config != null && velXZ.magnitude > _config.maxSwingSpeed)
            {
                velXZ = velXZ.normalized * _config.maxSwingSpeed;
                _rb.velocity = new Vector3(velXZ.x, _rb.velocity.y, velXZ.z);
            }
        }

        // Suppress character controller each step (it auto-resets to 1)
        if (_controller != null) _controller.SteeringControl = 0f;
    }

    private void UpdatePullPhysics()
    {
        if (_pullBody == null) { EndGrapple(false); return; }

        _pullElapsed += Time.fixedDeltaTime;
        if (_config != null && _pullElapsed >= _config.pullTimeout)
        {
            EndGrapple(false);
            return;
        }

        // Battery drain while pulling
        var battery = RobotBattery.Instance;
        if (battery != null && battery.Settings != null && battery.Settings.pullCostPerSecond > 0f)
        {
            battery.DrainOverTime(battery.Settings.pullCostPerSecond);
            if (battery.IsEmpty) { EndGrapple(false); return; }
        }

        // Pull the object toward the player's hand
        Vector3 target = HandPoint;
        Vector3 to = target - _pullBody.position;

        float stopRadius = _config != null ? _config.stopRadius : 0.8f;
        if (to.magnitude <= stopRadius)
        {
            EndGrapple(false);
            return;
        }

        float pullForce = _config != null ? _config.pullForce : 55f;
        float maxPullSpeed = _config != null ? _config.maxPullSpeed : 14f;

        _pullBody.AddForce(to.normalized * pullForce, ForceMode.Acceleration);
        if (_pullBody.velocity.magnitude > maxPullSpeed)
            _pullBody.velocity = _pullBody.velocity.normalized * maxPullSpeed;
    }

    // ── End grapple ─────────────────────────────────────────────────────────

    private void EndGrapple(bool preserveMomentum)
    {
        // Publish end events
        if (GameEventBus.Instance != null)
        {
            if (_activeAnchor != null)
                GameEventBus.Instance.Publish(new RopeGrappleEnded(_activeAnchor));
            if (_activePullable != null)
                GameEventBus.Instance.Publish(new RopePullEnded(_activePullable));
        }

        // 2.5D: on swing release, just let momentum carry — no forced vertical boost.
        // The player keeps their current XZ swing velocity (tangential) plus whatever
        // Y velocity they have from gravity/jumps.

        // Restore character controller
        if (_controller != null) _controller.SteeringControl = 1f;

        _state = GrappleState.Idle;
        _pullBody = null;
        _swingElapsed = 0f;
        _pullElapsed = 0f;
        _activeAnchor = null;
        _activePullable = null;
    }

    // ── LateUpdate: rope visual ─────────────────────────────────────────────

    private void LateUpdate()
    {
        if (_ropeLine == null) return;

        switch (_state)
        {
            case GrappleState.Swinging:
                // Taut rope from hand to the actual world anchor (not Y-projected)
                DrawRope(HandPoint, _anchorWorldPos, slack: 0.02f);
                break;

            case GrappleState.PullingObject:
                if (_pullBody != null)
                    DrawRope(HandPoint, _pullBody.position, slack: 0.08f);
                else
                    _ropeLine.enabled = false;
                break;

            case GrappleState.Firing:
                // Handled in UpdateFiring
                break;

            default:
                _ropeLine.enabled = false;
                break;
        }
    }

    // ── Rope drawing with sag ───────────────────────────────────────────────

    /// <summary>
    /// Draw the rope from start to end with a parabolic sag.
    /// slack=0 → taut straight line; slack=0.3 → visible droop.
    /// </summary>
    private void DrawRope(Vector3 start, Vector3 end, float slack)
    {
        if (_ropeLine == null) return;

        _ropeLine.enabled = true;

        float dist = Vector3.Distance(start, end);

        for (int i = 0; i < RopeSegments; i++)
        {
            float t = (float)i / (RopeSegments - 1);
            Vector3 point = Vector3.Lerp(start, end, t);

            // Parabolic sag: max at middle, zero at ends
            float sagAmount = slack * 4f * t * (1f - t) * dist;
            point += Vector3.down * sagAmount;

            _ropePoints[i] = point;
        }

        _ropeLine.SetPositions(_ropePoints);
    }
}

