    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        bodyCollider = GetComponent<Collider>();
        rb.drag = groundDrag;
        rb.freezeRotation = true;
    }

    private void Update()
    {
        moveInput.x = Input.GetAxisRaw("Horizontal");
        moveInput.z = Input.GetAxisRaw("Vertical");
        RbVelocityDirection = rb.velocity.normalized;
        if (moveInput.sqrMagnitude > 1f) moveInput.Normalize();

        if (Input.GetButtonDown("Jump")) jumpQueued = true;
    }



    private void FixedUpdate()
    {
        UpdateGrounded();

        // Accelerate toward the input-driven target velocity (XZ only). External forces
        // (wind AddForce) and surface friction are left to the solver. SpeedMultiplier
        // lowers the target (water/mud slow); SteeringControl scales the force (ice = slidey,
        // weak steering so momentum carries, but never 0 so the player can't get stuck).
        Vector3 horizVel = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
        Vector3 inputDir = new Vector3(moveInput.x, 0f, moveInput.z);
        bool idle = inputDir.sqrMagnitude < 0.01f;
        // Latch low-grip: refresh the timer while the zone asserts it, otherwise decay it.
        // The brake stays off for the whole grace window, surviving single-step trigger gaps.
        if (LowGrip) lowGripTimer = lowGripGrace;
        else lowGripTimer -= Time.fixedDeltaTime;
        bool lowGrip = lowGripTimer > 0f;
        if (lowGrip)
        {
            // Ice: momentum carries, input only steers. With input, push in the input direction
            // WITHOUT the "- horizVel" brake term (that term is what kills the slide on normal
            // ground), so existing momentum is preserved and the velocity vector rotates toward
            // the input instead of being reset to it. Speed is capped to moveSpeed so the additive
            // force can't run away. Idle = no force, the frictionless surface keeps the glide.
            if (!idle)
            {
                rb.AddForce(inputDir * moveSpeed * acceleration * SteeringControl, ForceMode.Acceleration);
                Vector3 hv = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
                float maxSpeed = moveSpeed * SpeedMultiplier;
                if (hv.magnitude > maxSpeed)
                {
                    hv = hv.normalized * maxSpeed;
                    rb.velocity = new Vector3(hv.x, rb.velocity.y, hv.z);
                }
            }
        }
        else
        {
            // Normal ground: accelerate toward the input-driven target velocity (XZ only).
            // SpeedMultiplier lowers the target (water/mud slow); SteeringControl scales the
            // force (wind = weak self-correction so wind blows you).
            Vector3 targetVel = inputDir * moveSpeed * SpeedMultiplier;
            Vector3 dv = targetVel - horizVel;
            rb.AddForce(dv * acceleration * SteeringControl, ForceMode.Acceleration);
        }

        if (jumpQueued && isGrounded && CanJump)
        {
            Vector3 v = rb.velocity; v.y = 0f; rb.velocity = v;
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
            isGrounded = false;
            PublishEvent(new PlayerJumped(transform.position));
        }
        jumpQueued = false;

        // Per-step terrain modifiers; zones re-assert them in OnTriggerStay (which fires
        // after FixedUpdate within the same physics step).
        SteeringControl = 1f;
        SpeedMultiplier = 1f;
        CanJump = true;
        LowGrip = false;

        // Detect landing (was airborne, now grounded).
        if (!wasGrounded && isGrounded)
            PublishEvent(new PlayerLanded(transform.position));
        wasGrounded = isGrounded;
    }

    private void UpdateGrounded()
    {
        if (bodyCollider == null)
        {
            isGrounded = false;
            return;
        }

        Vector3 origin = bodyCollider.bounds.center;
        origin.y = bodyCollider.bounds.min.y + 0.02f;

        isGrounded = Physics.Raycast(
            origin,
            Vector3.down,
            groundCheckDistance,
            groundLayers,
            QueryTriggerInteraction.Ignore
        );
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        // Ground check ray
        if (bodyCollider != null)
        {
            Vector3 origin = bodyCollider.bounds.center;
            origin.y = bodyCollider.bounds.min.y + 0.02f;
            Debug.DrawLine(origin, origin + Vector3.down * groundCheckDistance,
                isGrounded ? Color.green : Color.red);
        }

        // Velocity vector
        if (rb != null)
        {
            Debug.DrawRay(transform.position, rb.velocity, Color.cyan);
        }
    }
#endif
}

using UnityEngine;
using UnityEngine.Events;
using Flynn.Events;

/// <summary>
/// Marks a world object as a harvestable resource and manages its runtime health.
/// Subscribes to <see cref="ResourceManager.OnResourceHit"/> so it only takes damage
/// when the player's hit targets this object (or a child collider). All static data
/// (required tool, max health, drops) lives in the assigned
/// <see cref="ResourceNodeConfig"/> ScriptableObject.
///
/// Designer-hookable events are exposed as UnityEvents in the Inspector:
///   • <see cref="OnHitEvent"/>      — after each hit that damages this node
///   • <see cref="OnDepletedEvent"/>  — when health reaches zero
///
/// AttackAnimIndex maps RequiredTool → Animator AttackIndex (1-4):
///   Pick = 1 | Axe = 2 | Hammer = 3 | Wrench = 4
/// </summary>
public class ResourceNode : MonoBehaviour
{
    // ── Inspector ─────────────────────────────────────────────────────────────

    [Tooltip("Data asset for this resource type (health, tool, drops). Create via Flynn/Resource/Node Config.")]
    [SerializeField] private ResourceNodeConfig _config;

    [Tooltip("Channel raised on each hit so the HUD can show a world-anchored HP bar. Optional.")]
    [SerializeField] private ResourceHitChannel _hitChannel;

    // ── UnityEvents (designer-hookable) ───────────────────────────────────────

    [Header("Events")]
    [Tooltip("Fired after each hit that damages this node. Argument = remaining health.")]
    [SerializeField] private IntEvent _onHitEvent = new IntEvent();

    [Tooltip("Fired when health reaches zero (before drops / destruction).")]
    [SerializeField] private UnityEvent _onDepletedEvent = new UnityEvent();

    // ── C# events (code-side subscribers) ─────────────────────────────────────

    /// <summary>Raised after each successful hit. Argument is remaining health.</summary>
    public event System.Action<int> OnDamaged;

    /// <summary>Raised when health reaches zero, before drops are spawned.</summary>
    public event System.Action OnDepleted;

    // ── Public properties ─────────────────────────────────────────────────────

    public ResourceNodeConfig Config => _config;

    /// <summary>Current remaining health this session.</summary>
    public int CurrentHealth { get; private set; }

    /// <summary>Maximum health from the config (1 when unconfigured).</summary>
    public int MaxHealth => _config != null ? Mathf.Max(1, _config.maxHealth) : 1;

    /// <summary>Remaining health as a 0-1 fraction.</summary>
    public float Health01 => Mathf.Clamp01((float)CurrentHealth / MaxHealth);

    private bool _depleted;

    /// <summary>Convenience accessor so callers don't have to null-check Config.</summary>
    public ItemType RequiredTool => _config != null ? _config.requiredTool : ItemType.Pick;

    /// <summary>Resource type for effectiveness lookups.</summary>
    public ResourceType ResourceType => _config != null ? _config.resourceType : ResourceType.None;

    /// <summary>Whether this node has been fully depleted this session.</summary>
    public bool IsDepleted => _depleted;

    /// <summary>Display label for hover UI.</summary>
    public string DisplayName => _config != null ? _config.displayName : "Resource";

    /// <summary>
    /// Animator AttackIndex value for this resource's required tool.
    /// Returns 0 when no valid tool is mapped.
    /// </summary>
    public int AttackAnimIndex => RequiredTool switch
    {
        ItemType.Pick   => 1,
        ItemType.Axe    => 2,
        ItemType.Hammer => 3,
        ItemType.Wrench => 4,
        _               => 0,
    };

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        CurrentHealth = _config != null ? _config.maxHealth : 1;
    }

    private void OnEnable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit += HandleResourceManagerHit;
    }

    private void OnDisable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit -= HandleResourceManagerHit;
    }

    // ── Public API ────────────────────────────────────────────────────────────

    /// <summary>
    /// Try to apply a tool hit to this node. Looks up tool effectiveness from the
    /// <see cref="ToolEffectivenessTable"/> on the <see cref="ResourceManager"/>.
    /// If the tool is ineffective (multiplier 0), the hit is rejected and a
    /// <see cref="ResourceHit"/> event is published with zero damage for "wrong tool" feedback.
    /// Returns true if the hit was accepted (even if no damage was dealt).
    /// </summary>
    public bool TryApplyToolHit(ToolHitContext hit)
    {
        if (_depleted) return false;

        float effectiveness = ResourceManager.Instance != null
            ? ResourceManager.Instance.GetEffectiveness(hit.ToolType, ResourceType)
            : 1f;

        int scaledDamage = Mathf.RoundToInt(hit.Damage * effectiveness);

        // Publish hit event regardless (for "wrong tool" feedback)
        PublishEvent(new ResourceHit(this, hit));

        if (scaledDamage <= 0) return false;

        ReceiveHit(scaledDamage);
        return true;
    }

    /// <summary>
    /// Apply <paramref name="damage"/> points to this node. When health reaches
    /// zero the node spawns its drops and destroys itself.
    /// </summary>
    /// <param name="damage">Positive integer damage value.</param>
    public void ReceiveHit(int damage)
    {
        if (CurrentHealth <= 0) return;

        CurrentHealth = Mathf.Max(0, CurrentHealth - damage);

        // C# event (code subscribers)
        OnDamaged?.Invoke(CurrentHealth);

        // UnityEvent (designer-hooked effects)
        _onHitEvent?.Invoke(CurrentHealth);

        // HUD channel
        if (_hitChannel != null) _hitChannel.Raise(this, Health01);

        // GameEventBus (decoupled feedback/audio/UI)
        PublishEvent(new ResourceDamaged(this, damage, CurrentHealth));

        if (CurrentHealth <= 0)
            Deplete();
    }

    // ── Private ───────────────────────────────────────────────────────────────

    /// <summary>
    /// Listener for <see cref="ResourceManager.OnResourceHit"/>. Only applies
    /// damage when the hit targets this object (or a child collider).
    /// </summary>
    private void HandleResourceManagerHit(PlayerHitInfo info)
    {
        if (info.Target == null) return;
        if (!IsThisResource(info.Target)) return;
        ReceiveHit(info.Power);
    }

    /// <summary>True if the target GameObject is this object or a descendant.</summary>
    private bool IsThisResource(GameObject target)
    {
        Transform t = target.transform;
        while (t != null)
        {
            if (t.gameObject == gameObject) return true;
            t = t.parent;
        }
        return false;
    }

    /// <summary>
    /// Node is exhausted. Raises events for the drop-spawner and death-fall
    /// listeners to react (eject drops, topple + fade). The node only destroys
    /// itself here as a fallback when no <see cref="ResourceDeathFall"/> is present
    /// to own the removal.
    /// </summary>
    private void Deplete()
    {
        if (_depleted) return;
        _depleted = true;

        // C# event (code subscribers)
        OnDepleted?.Invoke();

        // UnityEvent (designer-hooked effects)
        _onDepletedEvent?.Invoke();

        // GameEventBus (decoupled feedback/audio/UI)
        PublishEvent(new ResourceDepleted(this));

        if (GetComponent<ResourceDeathFall>() == null)
            Destroy(gameObject);
    }

    // ── Nested types ──────────────────────────────────────────────────────────

    /// <summary>UnityEvent passing remaining health as an int.</summary>
    [System.Serializable]
    public class IntEvent : UnityEvent<int> { }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;

/// <summary>
/// Describes a single inventory item. Assign via Inspector; instances live in
/// Assets/Flynn/Configs/Items/. The attackAnimIndex maps to the four attack
/// clips: 1 = pick, 2 = axe, 3 = hammer, 4 = wrench.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Item Definition", fileName = "ItemDefinition")]
public class ItemDefinition : ScriptableObject
{
    [Header("Identity")]
    public string itemId;
    public string displayName;
    public Sprite icon;

    [Header("Tool")]
    public ItemType itemType;

    [Tooltip("Animator AttackIndex (1-4) triggered when this tool swings. 0 = no attack.")]
    [Range(0, 4)]
    public int attackAnimIndex;

    [Header("Stacking")]
    [Tooltip("Maximum count of this item in one inventory slot. Tools (the wrench) should be 1.")]
    [Min(1)] public int maxStack = 3;

    [Header("World pickup")]
    [Tooltip("Prefab spawned to represent this item lying in / dropped into the world (carries a WorldItem). " +
             "Used by resource drops, the drop key, and drag-to-drop.")]
    public GameObject worldPrefab;

    [Tooltip("If true, world drops of this item fly to the player automatically once there's room. " +
             "If false (e.g. the wrench) the player must aim at it and press the pickup key.")]
    public bool autoCollect = true;

    [Header("Currency")]
    [Tooltip("If true this item is a currency: collecting it adds to currencyTarget instead of taking an inventory slot.")]
    public bool isCurrency = false;

    [Tooltip("Currency counter incremented when this item is collected. Only used when isCurrency is true.")]
    public IntVariable currencyTarget;

    /// <summary>True when this item should magnet to the player on drop (resources, currency).</summary>
    public bool AutoCollects => autoCollect || isCurrency;
}

/// <summary>
/// Identifies the kind of resource a ResourceNode represents. Used by
/// ToolEffectivenessTable to determine which tools are effective.
/// </summary>
public enum ResourceType
{
    None     = 0,
    Stone    = 1,
    Wood     = 2,
    TechTrash = 3,
    Unknown  = 4,
}

using UnityEngine;

/// <summary>
/// The visual/animation surface the player's combat &amp; interaction controllers drive,
/// decoupled from how the body is actually rendered. Implemented by both the legacy
/// sprite-sheet driver (<see cref="FlynnAnimationDriver"/>) and the procedural cube-rig
/// driver (<see cref="ProceduralCharacterDriver"/>) so the same wrench/throw/rope/reticle
/// logic works against either body without edits.
///
/// Controllers resolve it via <c>GetComponent&lt;IPlayerVisual&gt;()</c> in Awake.
/// </summary>
public interface IPlayerVisual
{
    /// <summary>World-space "hand" / chest origin for thrown projectiles and the rope end.</summary>
    Vector3 VisualCenter { get; }

    /// <summary>VisualCenter projected to the character's foot Y (ground-plane indicators).</summary>
    Vector3 VisualGroundCenter { get; }

    /// <summary>True while an attack/swing is playing (gates re-triggering).</summary>
    bool IsAttacking { get; }

    /// <summary>Fire the attack pose for the given tool index (1=pick 2=axe 3=hammer 4=wrench).</summary>
    void TriggerAttack(int animIndex);

    /// <summary>Enter the windup hold for the given tool index.</summary>
    void BeginChargePose(int animIndex);

    /// <summary>Scrub the windup pose with charge fraction 0→1 (also live-swaps the tool).</summary>
    void UpdateChargePose(int animIndex, float charge01);

    /// <summary>Release the swing at the given playback speed (higher = faster follow-through).</summary>
    void ReleaseSwing(int animIndex, float animSpeed);

    /// <summary>Abort a windup and return to neutral.</summary>
    void CancelSwing();

    /// <summary>Orient the body toward a world-space XZ direction. Ignores Y; no-op on zero.</summary>
    void FaceWorldDirection(Vector3 worldDir);
}

using UnityEngine;
using UnityEngine.UIElements;

/// <summary>
/// Screen-space interaction tag that follows the mouse cursor while an
/// interactable is hovered. Driven by <see cref="WorldInteractTagPresenter"/>
/// when a hover is active the presenter calls <see cref="Show"/> with the
/// prompt text; the tag then follows the cursor each frame until
/// <see cref="HideTag"/> is called.
///
/// Lives as a pre-existing UIDocument under the UI manager so designers can
/// customise the UXML/USS. Uses the Flynn mono palette (black bg, 1px white outline).
/// </summary>
public class InteractTagPanel : UIToolkitPanel
{
    private Label _label;
    private VisualElement _root;

    protected override bool Bind(VisualElement root)
    {
        _root = root.Q<VisualElement>("InteractTagRoot");
        _label = root.Q<Label>("InteractTagLabel");
        return _root != null && _label != null;
    }

    private void LateUpdate()
    {
        if (!IsVisible || _root == null) return;

        var panel = _root.panel;
        if (panel == null) return;

        Vector2 mouse = Input.mousePosition;
        var contentRect = panel.visualTree.layout;
        float scaleX = contentRect.width > 0 ? Screen.width / contentRect.width : 1f;
        float scaleY = contentRect.height > 0 ? Screen.height / contentRect.height : 1f;

        _root.style.left = mouse.x / scaleX;
        _root.style.top = (Screen.height - mouse.y) / scaleY;
    }

    /// <summary>Show the tag with the given prompt text. It will follow the mouse cursor.</summary>
    public void Show(string text)
    {
        if (_label != null) _label.text = text;
        if (_root != null) _root.style.display = DisplayStyle.Flex;
        IsVisible = true;
        ApplyRootDisplay();
    }

    /// <summary>Hide the tag.</summary>
    public void HideTag()
    {
        if (_root != null) _root.style.display = DisplayStyle.None;
        IsVisible = false;
        ApplyRootDisplay();
    }

    private void ApplyRootDisplay()
    {
        if (Root != null)
            Root.style.display = IsVisible ? DisplayStyle.Flex : DisplayStyle.None;
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;
using Flynn.Events;

/// <summary>
/// Screen-space UI Toolkit panel that projects floating HP bars above ResourceNodes.
/// Driven by <see cref="UIManager"/> as <see cref="UIPanelId.ResourceHP"/>. Subscribes
/// to <see cref="ResourceDamaged"/> / <see cref="ResourceDepleted"/> on GameEventBus
/// and pools VisualElement bars. Bars are positioned by projecting world-space node
/// positions to panel coordinates via RuntimePanelUtils.
///
/// Bar style: white fill depleting left→right on a black background (Flynn mono).
/// Lives as a UIDocument under MANAGERS/UI.
/// </summary>
[RequireComponent(typeof(UIDocument))]
public class ResourceHPPanel : UIToolkitPanel
{
    [Header("Appearance")]
    [Tooltip("World-space height offset above the node origin.")]
    [SerializeField] private float _heightOffset = 1.6f;

    [Header("Timing")]
    [Tooltip("Seconds to keep the bar visible after the last hit.")]
    [SerializeField] private float _displayDuration = 3f;

    [Tooltip("Seconds for the fade-out animation.")]
    [SerializeField] private float _fadeDuration = 0.5f;

    [Tooltip("UXML template for a single health bar instance.")]
    [SerializeField] private VisualTreeAsset _healthBarTemplate;

    // ── Event bus subscription state ────────────────────────────────────────

    private bool _subscribed;

    // ── Pool & active tracking ─────────────────────────────────────────────

    private readonly Stack<VisualElement> _pool = new();
    private readonly Dictionary<ResourceNode, BarEntry> _active = new();

    private VisualElement _root;

    private struct BarEntry
    {
        public VisualElement Bar;
        public VisualElement Fill;
        public float HideTime;
        public bool Fading;
    }

    // ── Unity messages ──────────────────────────────────────────────────────

    protected override void OnEnable()
    {
        base.OnEnable();
        if (GameEventBus.Instance != null)
        {
            GameEventBus.Instance.Subscribe<ResourceDamaged>(OnResourceDamaged);
            GameEventBus.Instance.Subscribe<ResourceDepleted>(OnResourceDepleted);
        }
    }

    private void OnDisable()
    {
        if (GameEventBus.Instance != null && _subscribed)
        {
            GameEventBus.Instance.Unsubscribe<ResourceDamaged>(OnResourceDamaged);
            GameEventBus.Instance.Unsubscribe<ResourceDepleted>(OnResourceDepleted);
            _subscribed = false;
        }
    }

    private void TrySubscribe()
    {
        if (_subscribed || GameEventBus.Instance == null) return;
        GameEventBus.Instance.Subscribe<ResourceDamaged>(OnResourceDamaged);
        GameEventBus.Instance.Subscribe<ResourceDepleted>(OnResourceDepleted);
        _subscribed = true;
    }

    private void LateUpdate()
    {
        TrySubscribe();

        if (_root == null || Camera.main == null) return;

        float now = Time.time;
        List<ResourceNode> toRelease = null;

        foreach (var kvp in _active)
        {
            var node = kvp.Key;
            var entry = kvp.Value;

            // Node destroyed — release immediately
            if (node == null)
            {
                if (toRelease == null) toRelease = new List<ResourceNode>();
                toRelease.Add(node);
                continue;
            }

            // Project world position to panel coordinates
            Vector3 worldPos = node.transform.position + Vector3.up * _heightOffset;
            Vector2 panelPos = RuntimePanelUtils.CameraTransformWorldToPanel(
                _root.panel, worldPos, Camera.main);

            // Offset so bar centers above the node
            float barWidth = entry.Bar.resolvedStyle.width;
            entry.Bar.style.left = panelPos.x - barWidth * 0.5f;
            entry.Bar.style.top = panelPos.y;

            // Start fading when timer expires
            if (!entry.Fading && now >= entry.HideTime)
            {
                entry.Fading = true;
                entry.Bar.AddToClassList("health-bar--fading");
                entry.Bar.style.transitionDuration =
                    new List<TimeValue> { new TimeValue(_fadeDuration) };
            }

            // Check if fade finished
            if (entry.Fading && now >= entry.HideTime + _fadeDuration)
            {
                if (toRelease == null) toRelease = new List<ResourceNode>();
                toRelease.Add(node);
            }
        }

        if (toRelease != null)
        {
            foreach (var node in toRelease)
                ReleaseBar(node);
        }
    }

    // ── Binding ─────────────────────────────────────────────────────────────

    protected override bool Bind(VisualElement root)
    {
        _root = root.Q<VisualElement>("ResourceHPRoot");
        return _root != null;
    }

    // ── Event handlers ──────────────────────────────────────────────────────

    private void OnResourceDamaged(ResourceDamaged evt)
    {
        if (evt.Node == null || _root == null) return;

        if (!_active.TryGetValue(evt.Node, out var entry))
        {
            entry = AcquireBar(evt.Node);
            if (entry.Bar == null) return;
        }

        // Update fill width — white shrinks as HP depletes, revealing black bg
        float ratio = evt.Node.MaxHealth > 0
            ? (float)evt.RemainingHp / evt.Node.MaxHealth : 0f;
        entry.Fill.style.width = new StyleLength(Length.Percent(ratio * 100f));

        // Show and reset timer
        entry.Bar.AddToClassList("health-bar--visible");
        entry.Bar.RemoveFromClassList("health-bar--fading");
        entry.Bar.style.opacity = 1f;
        entry.Bar.style.transitionDuration = StyleKeyword.Null;
        entry.Fading = false;
        entry.HideTime = Time.time + _displayDuration;

        _active[evt.Node] = entry;
    }

    private void OnResourceDepleted(ResourceDepleted evt)
    {
        if (evt.Node == null) return;
        if (!_active.TryGetValue(evt.Node, out var entry)) return;

        entry.Fill.style.width = 0f;
        entry.Fading = true;
        entry.HideTime = Time.time;
        entry.Bar.AddToClassList("health-bar--fading");
        entry.Bar.style.transitionDuration =
            new List<TimeValue> { new TimeValue(_fadeDuration) };

        _active[evt.Node] = entry;
    }

    // ── Pool acquire / release ──────────────────────────────────────────────

    private BarEntry AcquireBar(ResourceNode node)
    {
        VisualElement bar;
        if (_pool.Count > 0)
        {
            bar = _pool.Pop();
        }
        else
        {
            bar = CreateBarElement();
        }

        bar.name = $"HPBar_{node.name}";
        _root.Add(bar);

        var fill = bar.Q<VisualElement>("BarFill");
        var entry = new BarEntry
        {
            Bar = bar,
            Fill = fill,
            HideTime = Time.time + _displayDuration,
            Fading = false,
        };

        _active[node] = entry;
        return entry;
    }

    private void ReleaseBar(ResourceNode node)
    {
        if (!_active.TryGetValue(node, out var entry)) return;

        entry.Bar.RemoveFromClassList("health-bar--visible");
        entry.Bar.RemoveFromClassList("health-bar--fading");
        entry.Bar.style.opacity = StyleKeyword.Null;
        entry.Bar.style.transitionDuration = StyleKeyword.Null;
        entry.Fill.style.width = new StyleLength(Length.Percent(100f));
        entry.Bar.name = "HealthBar_Pooled";

        _root.Remove(entry.Bar);
        _active.Remove(node);
        _pool.Push(entry.Bar);
    }

    // ── Bar element factory ─────────────────────────────────────────────────

    private VisualElement CreateBarElement()
    {
        if (_healthBarTemplate != null)
        {
            var container = _healthBarTemplate.CloneTree();
            return container.ElementAt(0) ?? container;
        }

        // Fallback: build in code (should not happen when template is assigned)
        var bar = new VisualElement { name = "HealthBar" };
        bar.AddToClassList("health-bar");

        var bg = new VisualElement { name = "BarBackground" };
        bg.AddToClassList("health-bar__bg");

        var fill = new VisualElement { name = "BarFill" };
        fill.AddToClassList("health-bar__fill");

        bg.Add(fill);
        bar.Add(bg);
        return bar;
    }
}

using System;
using UnityEngine;

/// <summary>
/// One inventory slot: an item kind plus how many of it are stacked here.
/// A slot holds a single item kind; the stack is capped by <see cref="ItemDefinition.maxStack"/>.
/// Kept as a small value type so the inventory model stays flat and expandable.
/// </summary>
[Serializable]
public struct InventorySlot
{
    public ItemDefinition item;
    public int count;

    public bool IsEmpty => item == null || count <= 0;

    /// <summary>Stack cap for whatever item this slot holds (1 when empty).</summary>
    public int MaxStack => item != null ? Mathf.Max(1, item.maxStack) : 1;

    public bool IsFull => !IsEmpty && count >= MaxStack;

    /// <summary>How many more of this item the slot can still take (0 when empty or full).</summary>
    public int SpaceLeft => IsEmpty ? 0 : Mathf.Max(0, MaxStack - count);

    public static InventorySlot Empty => new InventorySlot { item = null, count = 0 };

    public static InventorySlot Of(ItemDefinition item, int count)
        => new InventorySlot { item = item, count = item != null ? Mathf.Max(0, count) : 0 };
}
